using Microsoft.Extensions.AI;

public enum AgentExecutionStatus
{
    Running,
    Completed,
    WaitingForHumanApproval,
    Failed,
    ExceededBudget
}

public class AgentCheckpoint
{
    public string ExecutionId { get; set; } = Guid.NewGuid().ToString();
    public int CurrentStep { get; set; }
    public List<ChatMessage> ConversationHistory { get; set; } = new();
    public AgentExecutionStatus Status { get; set; }
    public string? PendingToolCallId { get; set; }
    public string? PendingToolName { get; set; }
    public Dictionary<string, object>? PendingToolArgs { get; set; }
}

public class ResilientAgentRunner
{
    private readonly IChatClient _chatClient;
    private readonly IAgentCheckpointStore _checkpointStore;
    private readonly IToolDispatcher _toolDispatcher;
    private const int MaxAllowedSteps = 10;
    private static readonly TimeSpan StepTimeout = TimeSpan.FromSeconds(30);

    public ResilientAgentRunner(
        IChatClient chatClient,
        IAgentCheckpointStore checkpointStore,
        IToolDispatcher toolDispatcher)
    {
        _chatClient = chatClient;
        _checkpointStore = checkpointStore;
        _toolDispatcher = toolDispatcher;
    }

    public async Task<AgentCheckpoint> StepAsync(AgentCheckpoint checkpoint, CancellationToken ct = default)
    {
        // 1. Guard against runaway infinite loops
        if (checkpoint.CurrentStep >= MaxAllowedSteps)
        {
            checkpoint.Status = AgentExecutionStatus.ExceededBudget;
            await _checkpointStore.SaveAsync(checkpoint, ct);
            return checkpoint;
        }

        checkpoint.CurrentStep++;
        checkpoint.Status = AgentExecutionStatus.Running;

        // 2. Invoke model with per-step timeout
        using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
        timeoutCts.CancelAfter(StepTimeout);

        var options = new ChatOptions
        {
            Tools = _toolDispatcher.GetAvailableTools(),
            Temperature = 0.2f
        };

        ChatCompletion response = await _chatClient.CompleteAsync(
            checkpoint.ConversationHistory,
            options,
            timeoutCts.Token);

        checkpoint.ConversationHistory.Add(response.Message);

        // 3. Check for tool invocations
        var functionCall = response.Message.Contents.OfType<FunctionCallContent>().FirstOrDefault();
        if (functionCall != null)
        {
            // 4. Validate if tool requires human approval (e.g. money transfer, delete, email send)
            if (_toolDispatcher.RequiresHumanApproval(functionCall.Name))
            {
                checkpoint.Status = AgentExecutionStatus.WaitingForHumanApproval;
                checkpoint.PendingToolCallId = functionCall.CallId;
                checkpoint.PendingToolName = functionCall.Name;
                checkpoint.PendingToolArgs = functionCall.Arguments as Dictionary<string, object>;

                await _checkpointStore.SaveAsync(checkpoint, ct);
                return checkpoint; // Suspends execution until approved
            }

            // 5. Execute safe tool directly and record result
            var toolResult = await _toolDispatcher.ExecuteAsync(functionCall, ct);
            checkpoint.ConversationHistory.Add(new ChatMessage(ChatRole.Tool, toolResult)
            {
                Contents = { new FunctionResultContent(functionCall.CallId, toolResult) }
            });
        }
        else
        {
            checkpoint.Status = AgentExecutionStatus.Completed;
        }

        await _checkpointStore.SaveAsync(checkpoint, ct);
        return checkpoint;
    }

    public async Task<AgentCheckpoint> ResumeAfterApprovalAsync(
        string executionId,
        bool approved,
        CancellationToken ct = default)
    {
        var checkpoint = await _checkpointStore.LoadAsync(executionId, ct)
            ?? throw new KeyNotFoundException($"Checkpoint {executionId} not found.");

        if (checkpoint.Status != AgentExecutionStatus.WaitingForHumanApproval)
            throw new InvalidOperationException("Agent is not awaiting approval.");

        if (!approved)
        {
            checkpoint.ConversationHistory.Add(new ChatMessage(ChatRole.Tool, "User rejected this action.")
            {
                Contents = { new FunctionResultContent(checkpoint.PendingToolCallId!, "REJECTED_BY_OPERATOR") }
            });
            checkpoint.Status = AgentExecutionStatus.Running;
            return await StepAsync(checkpoint, ct);
        }

        // Execute approved tool
        var result = await _toolDispatcher.ExecuteApprovedAsync(
            checkpoint.PendingToolName!,
            checkpoint.PendingToolArgs!,
            ct);

        checkpoint.ConversationHistory.Add(new ChatMessage(ChatRole.Tool, result)
        {
            Contents = { new FunctionResultContent(checkpoint.PendingToolCallId!, result) }
        });

        checkpoint.PendingToolCallId = null;
        checkpoint.PendingToolName = null;
        checkpoint.PendingToolArgs = null;
        checkpoint.Status = AgentExecutionStatus.Running;

        return await StepAsync(checkpoint, ct);
    }
}
